content.text:
{
  "name": "基于IVVI的电流源",
  "name_en": "IVVI-based current source",
  "manufacturer": "",
  "description": "一种利用IVVI电压输出经转换电路产生可调电流的实验室偏置源，常用于为低温电子学、纳米器件或量子器件提供稳定电流偏置，并可通过换算或测量评估输出电流与负载电阻。",
  "description_en": "A laboratory bias source that uses an IVVI voltage output with a conversion circuit to generate adjustable current. It is commonly used to provide stable current bias for cryogenic electronics, nanodevices, or quantum devices, and to estimate or measure output current and load resistance.",
  "actions": [
    {
      "action_name": "auto-seti",
      "description": "设置输出电流。",
      "description_en": "Set the output current."
    },
    {
      "action_name": "auto-ItomV",
      "description": "将目标电流换算为对应的控制电压。",
      "description_en": "Convert a target current to the corresponding control voltage."
    },
    {
      "action_name": "auto-mVtoI",
      "description": "将控制电压换算为对应的输出电流。",
      "description_en": "Convert a control voltage to the corresponding output current."
    },
    {
      "action_name": "auto-measurei",
      "description": "测量输出电流。",
      "description_en": "Measure the output current."
    },
    {
      "action_name": "auto-measureR",
      "description": "测量或估算负载电阻。",
      "description_en": "Measure or estimate the load resistance."
    }
  ],
  "tag_hints": [
    "current source",
    "IVVI rack",
    "low-noise biasing",
    "cryogenic electronics",
    "quantum device bias",
    "current-voltage conversion",
    "resistance measurement"
  ]
}

